Lemma tw_img : forall a k, 0x10000 <= a -> a + k <= SEGTOP_A -> (a + k <= 0x1ebc48 \/ 0x5fbc70 <= a) -> disjoint_from W_tail a k.
Proof using HA Hn Hca LOW LOR SPT SPA.
