Lemma tl_room : rz_size n + ru8 n <= S /\ rz_size n + 16 <= S /\ Z.of_nat (length (ushadow n)) = ru8 n / 8 /\ n <= ru8 n < n + 8
  /\ ru8 n mod 8 = 0.
